/**
 * Reconstructs corpus.core.frozen.json (titleForge series-name corpus v1.0.0,
 * n=303 CORE) from a compact per-record table, so the repetitive label fields
 * (object-form labels, structural-family labels, …) are derived rather than
 * repeated 303 times and the transcription surface stays small.
 *
 * `node build-corpus.mjs` writes corpus.core.frozen.json; `node derive.mjs`
 * then turns that into series-shapes.json / series-weights.json.
 *
 * ROWS tuple order:
 *   0 id | 1 name | 2 primaryGenre | 3 secondaryGenres(space-sep) |
 *   4 audience("" -> null) | 5 objectForm | 6 namingFocus | 7 umbrellaStatus |
 *   8 confidence | 9 properName | 10 bloc("" -> null) | 11 sourceType |
 *   12 wordCount | 13 articleType | 14 initialWord | 15 connectors(space-sep) |
 *   16 numberType("" -> not present) | 17 punctuation(space-sep) |
 *   18 formalDesignation | 19 structuralFamily | 20 familySource |
 *   21 medium("" -> M01) | 22 aliases(" | "-sep) | 23 normKey | 24 sourceNote("" -> null)
 */

import { writeFileSync } from "node:fs";

const OBJECT_FORM_LABEL = {
	OF01: "Narrative Series", OF02: "Franchise", OF03: "Shared Universe/World",
	OF05: "Recurring/Linked Collection", OF06: "Anthology Brand",
};
const NAMING_FOCUS_LABEL = {
	NF01: "Character", NF02: "Character Group", NF03: "Family/Lineage",
	NF04: "Place", NF05: "World/Universe", NF06: "Institution/Organisation",
	NF07: "Role/Profession", NF08: "Event/Conflict", NF09: "Object/Artefact",
	NF10: "Record/Text/Document", NF11: "Abstract Concept", NF12: "Brand/Property",
	NF13: "Mixed",
};
const GENRE_LABEL = {
	G01: "Fantasy", G02: "Science Fiction", G03: "Mystery/Crime", G04: "Thriller",
	G05: "Romance", G06: "Horror", G07: "Historical", G08: "Literary",
	G09: "Adventure", G10: "Western", G11: "Comedy/Humour",
};
const STATUS_LABEL = {
	NS01: "Official", NS02: "Established/Commonly Recognised",
	NS04: "Retrospective/Conventional",
};
const FAMILY_LABEL = {
	SF01: "Simple Nominal", SF02: "Compound Nominal", SF03: "Prepositional Nominal",
	SF04: "Coordinated/Conjoined", SF05: "Proper-Name Construction",
	SF08: "Clause-Like/Extended Phrase", SF09: "Verbal Construction",
	SF10: "Punctuation-Bipartite",
};

const list = (s) => (s ? s.split(" ").filter(Boolean) : []);

function record(r) {
	const [
		id, name, primaryGenre, secondaryGenres, audience, objectForm, namingFocus,
		umbrellaStatus, confidence, properName, bloc, sourceType, wordCount,
		articleType, initialWord, connectors, numberType, punctuation,
		formalDesignation, structuralFamily, familySource, medium, aliases, normKey,
		sourceNote,
	] = r;
	return {
		id,
		canonical_series_name: name,
		aliases: aliases ? aliases.split(" | ") : [],
		object_form: objectForm,
		object_form_label: OBJECT_FORM_LABEL[objectForm],
		naming_focus: namingFocus,
		naming_focus_label: NAMING_FOCUS_LABEL[namingFocus],
		primary_genre: primaryGenre,
		primary_genre_label: GENRE_LABEL[primaryGenre],
		secondary_genres: list(secondaryGenres),
		audience: audience || null,
		medium: medium || "M01",
		umbrella_name_status: umbrellaStatus,
		umbrella_name_status_label: STATUS_LABEL[umbrellaStatus],
		confidence,
		inclusion_status: "CORE",
		proper_name_presence: properName,
		bloc_bias: bloc || null,
		source_type: sourceType,
		source_note: sourceNote || null,
		rejection_reason: null,
		exact_word_count: wordCount,
		article_type: articleType,
		initial_word: initialWord,
		connectors: list(connectors),
		number_present: Boolean(numberType),
		number_type: numberType || null,
		punctuation: list(punctuation),
		formal_umbrella_designation: formalDesignation,
		structural_family: structuralFamily,
		structural_family_label: FAMILY_LABEL[structuralFamily],
		structural_family_auto: familySource === "manual" ? "SF02" : structuralFamily,
		structural_family_source: familySource,
		norm_key: normKey,
	};
}

